@push('scripts')<script>$(function(){var $t=$('#clearing-table'),x=$.fn.dataTable.render.text(),filters=function(){return {status:$('#clearing-status').val(),petty_cash_fund_id:$('#clearing-fund').val(),date_from:$('#clearing-date-from').val(),date_to:$('#clearing-date-to').val()};},labels={DRAFT:'ร่าง',SUBMITTED:'รออนุมัติ',APPROVED:'อนุมัติแล้ว',POSTED:'ลงบัญชีแล้ว',REVERSED:'ยกเลิกรายการแล้ว',VOID:'ยกเลิก'},classes={DRAFT:'app-status-neutral',SUBMITTED:'app-status-info',APPROVED:'app-status-success',POSTED:'app-status-success',REVERSED:'app-status-danger',VOID:'app-status-danger'};var table=$t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:$t.data('url'),data:function(d){$.extend(d,filters());}},order:[[0,'desc']],buttons:[window.erpExcelButton($t,filters)],columns:[{data:'document_number',render:x.display},{data:'clearing_date_label',render:x.display},{data:'fund_label',render:x.display},{data:'expected_amount',className:'text-end',render:$.fn.dataTable.render.number(',','.',2)},{data:'actual_amount',className:'text-end',render:$.fn.dataTable.render.number(',','.',2)},{data:'variance_amount',className:'text-end',render:$.fn.dataTable.render.number(',','.',2)},{data:'status',render:function(v,t){return t==='display'?'<span class="badge '+(classes[v]||'app-status-neutral')+'">'+x.display(labels[v]||v)+'</span>':v;}},{data:null,orderable:false,searchable:false,className:'text-end text-nowrap',render:function(_,t,r){if(t!=='display')return '';var actions=['<a class="btn btn-sm btn-app-soft" href="'+x.display(r.show_url)+'" title="ดูรายละเอียด" aria-label="ดูรายละเอียด"><i class="bx bx-file-find" aria-hidden="true"></i></a>'];if(r.edit_url)actions.push('<a class="btn btn-sm btn-app-soft" href="'+x.display(r.edit_url)+'" title="แก้ไข" aria-label="แก้ไข"><i class="bx bx-edit" aria-hidden="true"></i></a>');if(r.delete_url)actions.push('<button class="btn btn-sm btn-app-danger js-delete-petty-clearing" type="button" data-url="'+x.display(r.delete_url)+'" title="ลบร่าง" aria-label="ลบร่าง"><i class="bx bx-trash" aria-hidden="true"></i></button>');return actions.join(' ');}}]}));$('#clearing-status,#clearing-fund,#clearing-date-from,#clearing-date-to').on('change',function(){table.ajax.reload();});$('#clearing-reset').on('click',function(){$('#clearing-status,#clearing-fund,#clearing-date-from,#clearing-date-to').val('');table.ajax.reload();});window.erpAjaxDelete({button:'.js-delete-petty-clearing',reload:'#clearing-table',confirm:'ยืนยันการลบเอกสารเคลียร์เงินสดย่อยฉบับร่างนี้หรือไม่?',confirmButtonText:'ลบร่าง',cancelButtonText:'กลับ'});});</script>@endpush
